// @category C6000
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.*;
import ghidra.program.model.symbol.SourceType;
import ghidra.program.model.pcode.Varnode;
import ghidra.pcode.exec.*;
import java.nio.file.*;
import java.util.*;
public class C6000CallerContinuationTest extends GhidraScript {
 static class Case {String name,error;long at,caller;boolean accepted;}
 long read(BytesPcodeExecutorState state,Varnode var)throws Exception{return BytesPcodeArithmetic.forLanguage(currentProgram.getLanguage()).toLong(state.getVar(var,PcodeExecutorStatePiece.Reason.INSPECT),PcodeArithmetic.Purpose.INSPECT);}
 long memory(BytesPcodeExecutorState state,long address)throws Exception{return BytesPcodeArithmetic.forLanguage(currentProgram.getLanguage()).toLong(state.getVar(toAddr(address),4,false,PcodeExecutorStatePiece.Reason.INSPECT),PcodeArithmetic.Purpose.INSPECT);}
 void equal(Object wanted,Object actual,String why){if(!Objects.equals(wanted,actual))throw new AssertionError(why+" expected="+wanted+" actual="+actual);}
 protected void run()throws Exception{
  c6000.C6000PacketContext.prime(currentProgram,monitor);var cases=new com.google.gson.Gson().fromJson(Files.readString(Paths.get(getScriptArgs()[0])),Case[].class);
  for(var item:cases){currentProgram.getFunctionManager().createFunction(item.name,toAddr(item.at),new AddressSet(toAddr(item.at),toAddr(item.at+255)),SourceType.USER_DEFINED);if(item.name.equals("unowned_caller")||item.name.equals("conflicting_owner"))currentProgram.getFunctionManager().createFunction(item.name+"_identity",toAddr(item.at+768),new AddressSet(toAddr(item.at+768),toAddr(item.at+799)),SourceType.USER_DEFINED);if(!item.name.equals("unowned_caller"))currentProgram.getFunctionManager().createFunction(item.name+"_caller",toAddr(item.caller),new AddressSet(toAddr(item.caller),toAddr(item.caller+255)),SourceType.USER_DEFINED);if(item.name.equals("foreign_callee"))currentProgram.getFunctionManager().createFunction(item.name+"_foreign",toAddr(item.at+512),new AddressSet(toAddr(item.at+512),toAddr(item.at+767)),SourceType.USER_DEFINED);}
  int accepted=0,refused=0,executed=0,entryRefused=0;var records=new ArrayList<Object>();
  for(var item:cases){var function=currentProgram.getFunctionManager().getFunctionAt(toAddr(item.at));int bytes=item.name.equals("insufficient_drain")?4:item.name.equals("out_of_plan_packet")?12:8;byte[] caller=new byte[32];currentProgram.getMemory().getBytes(toAddr(item.caller),caller);String hash=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(caller));if(item.name.equals("bad_hash"))hash=(hash.startsWith("0")?"1":"0")+hash.substring(1);
   long owner=item.name.equals("unowned_caller")||item.name.equals("conflicting_owner")?item.at+768:item.caller;List<Long> packets=bytes==4?List.of(item.caller):List.of(item.caller,item.caller+(bytes==12?8:4));var prior=item.name.equals("hazard_mismatch")?Set.of("A4"):Set.<String>of();var contract=new c6000.C6000PipelineCompiler.ReturnContinuation(item.caller,owner,packets,item.caller+bytes,hash,false,new c6000.C6000PipelineCompiler.TraceEntry(!item.name.equals("entry_not_drained"),prior),"Synthetic explicit caller and fixed entry B3; unchanged code and drained entry");
   c6000.C6000PipelineCompiler.TraceResult result;try{result=new c6000.C6000PipelineCompiler(currentProgram,function).compileTrace(contract);if(!item.accepted)throw new AssertionError("Accepted unsupported continuation "+item.name);accepted++;}catch(IllegalArgumentException error){if(item.accepted||!error.getMessage().contains(item.error))throw new AssertionError(item.name+" unexpected refusal "+error);refused++;println("EXPECTED_REFUSAL "+item.name+" "+error.getMessage());records.add(Map.of("case",item.name,"refused",true,"error",error.getMessage()));continue;}
   equal(item.caller+bytes,result.exitPc(),"declared trace exit PC");boolean ordinary=false;try{new c6000.C6000PipelineCompiler(currentProgram,function).compile();}catch(IllegalArgumentException error){if(!error.getMessage().contains("return leaves architectural pipeline effects pending"))throw error;ordinary=true;}if(!ordinary)throw new AssertionError("Ordinary compile accepted pending tail");
   if(item.name.equals("captured_old_B4")){boolean enableRefused=false;try{c6000.C6000PipelineSchedules.enable(currentProgram,function,"Synthetic drained entry test",Set.of(),monitor);}catch(IllegalArgumentException error){if(!error.getMessage().contains("return leaves architectural pipeline effects pending"))throw error;enableRefused=true;}if(!enableRefused)throw new AssertionError("Ordinary enable accepted pending tail");if(java.math.BigInteger.ONE.equals(currentProgram.getProgramContext().getValue(currentProgram.getRegister("c_schedule_entry"),toAddr(item.at),false)))throw new AssertionError("Refusal installed schedule");}
   boolean invalid=false;try{result.validateEntryB3(0x9000);}catch(IllegalArgumentException expected){invalid=true;entryRefused++;}if(!invalid)throw new AssertionError("Wrong initial B3 accepted");result.validateEntryB3(item.caller);
   var arithmetic=BytesPcodeArithmetic.forLanguage(currentProgram.getLanguage());var state=new BytesPcodeExecutorState(currentProgram.getLanguage(),PcodeStateCallbacks.NONE);for(var register:currentProgram.getLanguage().getRegisters())if(!register.isProcessorContext()&&register.getMinimumByteSize()==4)state.setVar(register,arithmetic.fromConst(0,4));
   for(var entry:Map.of("B3",item.caller,"A4",0x8000L,"B4",0x11223344L,"B5",0x22334455L,"A7",0x33445566L,"B10",2L,"A0",1L).entrySet())state.setVar(currentProgram.getRegister(entry.getKey()),arithmetic.fromConst(entry.getValue(),4));byte[] ram=new byte[128];Arrays.fill(ram,(byte)0x5a);state.setVar(toAddr(0x8000),ram.length,false,ram);
   var schedule=result.schedule();var executor=new PcodeExecutor<byte[]>((ghidra.app.plugin.processors.sleigh.SleighLanguage) currentProgram.getLanguage(), ghidra.pcode.exec.BytesPcodeArithmetic.forLanguage(currentProgram.getLanguage()), state, PcodeExecutorStatePiece.Reason.EXECUTE_READ);var library=PcodeUseropLibrary.<byte[]>nil();var frame=executor.begin(new ghidra.pcode.exec.PcodeProgram((ghidra.app.plugin.processors.sleigh.SleighLanguage) currentProgram.getLanguage(), Arrays.asList(schedule.code()),library.getSymbols((ghidra.app.plugin.processors.sleigh.SleighLanguage)currentProgram.getLanguage())) {});Map<Integer,c6000.C6000PipelineCompiler.TraceBoundary> points=new HashMap<>();for(var boundary:result.boundaries())points.put(boundary.pcodeIndex(),boundary);int steps=0,cycles=0,boundaryCycle=-1;boolean snapshot=false,first=false;
   while(!frame.isFinished()&&steps++<100000){int index=frame.index();Long pc=schedule.cycleStarts().get(index);if(pc!=null){cycles++;if(pc==item.caller){equal(boundaryCycle+1,cycles,"first caller advance");equal(0x5a5a5a5aL,memory(state,0x8000),"no store flushed before caller");equal(0x5a5a5a5aL,memory(state,0x8004),"second store not flushed");}if(pc==item.caller+4){equal(boundaryCycle+2,cycles,"second caller advance");equal(0x22334455L,memory(state,0x8000),"first store reaches E3 at one advance");equal(0x5a5a5a5aL,memory(state,0x8004),"second store remains pending until advance2");first=true;}}
    var boundary=points.get(index);if(boundary!=null){if(snapshot)throw new AssertionError("Repeated boundary");snapshot=true;boundaryCycle=cycles;equal(2,boundary.stores().size(),"pending two stores");for(int k=0;k<2;k++){var store=boundary.stores().get(k);equal(k+1,store.remainingAdvances(),"E3 remaining age");boolean disabled=item.name.equals("captured_store_predicate")&&k==1;equal(disabled?0L:1L,read(state,store.predicate()),"captured enabled");equal(0x8000L+(item.name.equals("updating_store_tails")?4*k:0),read(state,store.capturedInputs().get("A4")),"captured base");equal(disabled?0L:0x8000L+4*k,read(state,store.address()),"native captured address");equal(disabled?0L:k==0?0x22334455L:0x11223344L,read(state,store.value()),"native captured value");equal(k==0?0x22334455L:0x11223344L,read(state,store.capturedInputs().get(k==0?"B5":"B4")),"captured source");}}
    executor.step(frame,library);
   }
   if(!frame.isFinished()||!snapshot||!first)throw new AssertionError("Incomplete closed trace "+item.name);equal(item.caller+bytes,read(state,new Varnode(currentProgram.getRegister("PC").getAddress(),4)),"exit PC");equal(item.name.equals("captured_store_predicate")?0x5a5a5a5aL:0x11223344L,memory(state,0x8004),"second tail store E3 captured predicate/value");if(item.name.equals("updating_store_tails"))equal(0x8008L,read(state,new Varnode(currentProgram.getRegister("A4").getAddress(),4)),"base updates occurred once in callee E1");if(item.name.equals("captured_store_predicate"))equal(0L,read(state,new Varnode(currentProgram.getRegister("A0").getAddress(),4)),"caller changed predicate without resampling store guard");
   if(item.name.equals("caller_store_order"))equal(0x33445566L,memory(state,0x8000),"caller store follows callee store in E3 order");else equal(0x22334455L,memory(state,0x8000),"first tail store value");
   if(item.name.equals("caller_load_order"))equal(0x22334455L,read(state,new Varnode(currentProgram.getRegister("A6").getAddress(),4)),"caller E3 load sees older tail store");
   if(item.name.equals("captured_old_base")){equal(0x8008L,read(state,new Varnode(currentProgram.getRegister("A4").getAddress(),4)),"caller base overwrite");equal(0x5a5a5a5aL,memory(state,0x800c),"old store did not resample base");}
   if(item.name.equals("captured_old_B4")){equal(18L,read(state,new Varnode(currentProgram.getRegister("B4").getAddress(),4)),"caller ADDAD overwrite");equal(Set.of("B4"),result.outgoingE1Writes(),"outgoing hazard");}else equal(Set.of(),result.outgoingE1Writes(),"outgoing hazards drained");
   records.add(Map.of("case",item.name,"accepted",true,"cycles",cycles,"exitPC",Long.toHexString(item.caller+bytes),"outgoingE1Writes",result.outgoingE1Writes()));executed++;
  }
  Files.writeString(Paths.get(getScriptArgs()[1]),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(records));println("CONTINUATION_CONTRACT_TEST_OK accepted="+accepted+" refused="+refused+" executed="+executed+" entryRefused="+entryRefused);
 }
}
